                    2 to "AppTraces holds log lines. A metric is not a log message.",
                    3 to "That returns one random row, not a total.",
                ),
            ),
            B.q("ai-m3-60", "ai-kql", "You want only the most recent console line from each revision of the container app. Which query?", listOf("ContainerAppConsoleLogs_CL | take 1", "ContainerAppConsoleLogs_CL | order by TimeGenerated desc", "ContainerAppConsoleLogs_CL | summarize count() by RevisionName_s", "ContainerAppConsoleLogs_CL | summarize arg_max(TimeGenerated, *) by RevisionName_s"), setOf(3), "arg_max(TimeGenerated, *) keeps, for each group, the whole row with the latest TimeGenerated, so you get one row, the newest, per revision.",
                scenario = "Parcelly runs two revisions of its API side by side during a canary release and wants to see what each printed last.",
                whyWrong = mapOf(
